    S.c('#e5dccb'); { const Q2 = [Fc(-12, 0, Wc/2), Fc(12, 0, Wc/2), Fc(12, 0, Wc/2 + 4.2), Fc(-12, 0, Wc/2 + 4.2)].map(p => [p[0], p[2]]); prism(S, ccw(Q2), gb - 0.2, gb + 0.3); }
    cnRoof(S, Fc, Lc + 3, Wc + 7, gb + 8.4, 2.2, {over:0.8, lift:0.7, k:Lc/2 + 3, pw:1.2, col:'#3f7d68', finial:false});
