        M.s.c('#596067'); seg(M.s, [x, g - 0.3, z], [x, g + hh, z], r.c === 12 ? 0.06 : 0.1, 4); boxV(M.lamp, r.c === 12 ? 0.35 : 0.7, 0.25, r.c === 12 ? 0.35 : 0.4, x, g + hh, z);
