        V.c('#b9bcbc'); V.q4(p[0] + nx, gp, p[1] + nz, q[0] + nx, gq, q[1] + nz, q[0] + nx, gq + 0.25, q[1] + nz, p[0] + nx, gp + 0.25, p[1] + nz); V.q4(p[0] - nx, gp, p[1] - nz, q[0] - nx, gq, q[1] - nz, q[0] - nx, gq + 0.25, q[1] - nz, p[0] - nx, gp + 0.25, p[1] - nz);
