// ---------- local terrain repair ----------
// The app's terrain (s2_terrain.py) sets the ground round "significant" fresh water to the water body's level, and computes that level
// from bank heights in which the hill term is suppressed near any water (sm(0, 120, dcoast) with dcoast measured to fresh water too):
// Nanyang Lake and the two covered PUB service reservoirs on the hill get a level of ~2 m, which leaves two ~40 m deep pits in the
// middle of the campus. Refill those terrain vertices (harmonic interpolation from the surrounding ground) before the terrain mesh is
// built. Only vertices inside the keep that are below 10 m (the campus is 25-55 m) are touched: a no-op once the data is fixed.
const ntuTerrainFix = () => {
  if (typeof H === 'undefined' || typeof TN === 'undefined' || !H || !SGR.on) return 0;
  const q = sgXY(1.3470, 103.6820), ax = q[0], ay = q[1], pit = [], isPit = new Set();
  const i0 = Math.floor((ax - 750 + HALF)/TS), i1 = Math.ceil((ax + 950 + HALF)/TS), j0 = Math.floor((ay - 850 + HALF)/TS), j1 = Math.ceil((ay + 1150 + HALF)/TS);
  for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++){ const x = -HALF + i*TS - ax, z = -(-HALF + j*TS - ay), k = j*TN + i; if (inPoly(NTU_KEEP, x, z) && H[k] < 10){ pit.push(k); isPit.add(k); } }
  if (!pit.length) return 0;
  for (const k of pit){ let s = 0, c = 0; for (let r = 1; r < 8 && !c; r++) for (let dj = -r; dj <= r; dj++) for (let di = -r; di <= r; di++){ const kk = k + dj*TN + di; if (!isPit.has(kk) && H[kk] > 10){ s += H[kk]; c++; } } H[k] = c ? s/c : 40; }
  for (let it = 0; it < 300; it++) for (const k of pit) H[k] = (H[k - 1] + H[k + 1] + H[k - TN] + H[k + TN])/4;
  return pit.length;
};
